import type { GasMix } from './dashboard.js';
import type {
  CurrentStrength,
  EntryType,
  SeaState,
  SuitType,
  TankMaterial,
  TimeOfDay,
  Weather,
} from './dives.js';

// Write contract of a dive: `POST /api/dives` (creation) and `PUT /api/dives/:id` (full
// replacement). Every field is required, `null` when not entered (D-22): an omitted field is a 400.

/** Shared by the dive team, written by the creator only (D-13, D-18). */
export interface DiveWriteEvent {
  /** Event id, generated by the client (D22); equal to `:id` on a `PUT`. */
  id: string;
  /** Equal to `site.id` of the request. */
  siteId: string;
  /** Instant of the immersion, ISO 8601 with an explicit offset (`2026-04-09T10:05:00+02:00`). */
  startedAt: string;
  utcOffsetMinutes: number;
  entryType: EntryType | null;
  timeOfDay: TimeOfDay | null;
  weather: Weather | null;
  airTemperatureC: number | null;
  seaState: SeaState | null;
  currentStrength: CurrentStrength | null;
  diveCenter: string | null;
}

/** The current diver's own measures and equipment (health data). */
export interface DiveWriteParticipation {
  maxDepthM: number;
  durationMin: number;
  waterTemperatureC: number | null;
  visibilityM: number | null;
  gasMix: GasMix;
  hasDecompression: boolean;
  stopsOk: boolean;
  notes: string | null;
  surfaceWaterTemperatureC: number | null;
  /** Both set or both `null` (RG-25). */
  safetyStopDurationMin: number | null;
  safetyStopDepthM: number | null;
  isRepetitive: boolean | null;
  /** Only with `gasMix: 'OTHER'` (RG-23). */
  o2Percent: number | null;
  tankVolumeL: number | null;
  tankMaterial: TankMaterial | null;
  startPressureBar: number | null;
  endPressureBar: number | null;
  suitType: SuitType | null;
  suitThicknessMm: number | null;
  weightKg: number | null;
}

/** A species seen during the dive; the order of the list is kept. */
export interface DiveWriteObservation {
  label: string;
  count: number | null;
}

/** The site of the dive: one of the diver's, or a new one known by its name only (`isNew`). */
export interface DiveWriteSite {
  id: string;
  name: string;
  isNew: boolean;
}

/** A buddy of the dive team: one of the diver's contacts, or a new one (`isNew`). */
export interface DiveWriteBuddy {
  id: string;
  firstName: string;
  lastName: string;
  /**
   * Level code (`N3`) of the contact (D-21). `null`: unchanged for an existing buddy, none for a
   * new one.
   */
  levelCode: string | null;
  isNew: boolean;
}

export interface DiveWriteRequest {
  event: DiveWriteEvent;
  participation: DiveWriteParticipation;
  /** 0 to 50, labels unique once trimmed. */
  observations: DiveWriteObservation[];
  site: DiveWriteSite;
  /** The dive team, in display order. */
  buddies: DiveWriteBuddy[];
  /** `updatedAt` of the detail read before editing; `null` for a creation (D-25). */
  baseUpdatedAt: string | null;
}

/** `201` on creation, `200` on a replayed creation or a replacement. */
export interface DiveWriteResponse {
  id: string;
  /** Logbook number, computed (D26). */
  number: number;
  /** Latest change of the event or the participation, ISO 8601 instant (UTC). */
  updatedAt: string;
}

/** Path of a field in the request body (`participation.maxDepthM`, `observations.3.label`) → codes. */
export type ApiFieldErrors = Record<string, string[]>;

/** `400` of a request that fails validation. Never carries the values received. */
export interface ApiValidationErrorResponse {
  statusCode: 400;
  code: 'validation-failed';
  fieldErrors: ApiFieldErrors;
}

export type ApiDomainErrorCode =
  | 'identifier-conflict'
  | 'full-sync-required'
  | 'site-in-use'
  | 'inactive-certification-level'
  | 'invalid-reference'
  | 'buddy-link-conflict'
  | 'unsupported-contract-value'
  | 'duplicate-observation'
  | 'too-many-observations'
  | 'merge-into-self'
  // Authentication, account and onboarding (D37 to D39, docs/plans/auth.md §3).
  | 'unauthenticated'
  | 'invalid-credentials'
  | 'too-many-attempts'
  | 'registration-closed'
  | 'email-taken'
  | 'onboarding-required'
  | 'onboarding-complete'
  | 'consent-required'
  | 'forbidden';

/**
 * Business error (D-26): `400`, `401`, `403`, `409`, `422`, `429` or `500` depending on the code.
 * A `429 too-many-attempts` also carries a `Retry-After` header (seconds).
 */
export interface ApiDomainErrorResponse {
  statusCode: number;
  code: ApiDomainErrorCode;
}
